<template>
  <div
    class="f-file"
    :class="[
      { 'f-file--disabled': disable, 'f-file--has-file': hasFile, 'f-file--dragging': isDragging },
      sizeClass
    ]"
    @dragover.prevent="onDragOver"
    @dragleave.prevent="onDragLeave"
    @drop.prevent="onDrop"
    @click="openFilePicker"
  >
    <input
      ref="fileInput"
      type="file"
      :accept="accept"
      :multiple="multiple"
      class="f-file__input"
      @change="onFileChange"
    />

    <!-- Empty state (no file selected) -->
    <div v-if="!hasFile" class="f-file__empty">
      <div class="f-file__icon">
        <q-icon :name="icon" :size="iconSize" />
      </div>
      <div class="f-file__text">
        <span class="f-file__action">{{ actionText }}</span>
        <span v-if="dragText" class="f-file__drag-text">{{ dragText }}</span>
      </div>
      <div v-if="hint" class="f-file__hint">{{ hint }}</div>
    </div>

    <!-- File selected state -->
    <div v-else class="f-file__selected">
      <div class="f-file__file-icon">
        <q-icon name="description" size="24px" />
      </div>
      <div class="f-file__file-info">
        <span class="f-file__file-name">{{ fileName }}</span>
        <span v-if="fileSize" class="f-file__file-size">{{ formattedFileSize }}</span>
      </div>
      <q-btn
        flat
        round
        dense
        icon="close"
        size="sm"
        class="f-file__clear-btn"
        @click.stop="clearFile"
      />
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, computed, ref, watch } from 'vue';

export default defineComponent({
  name: 'FellowFile',
  props: {
    modelValue: {
      type: [File, null] as any,
      default: null,
    },
    label: {
      type: String,
      default: '',
    },
    accept: {
      type: String,
      default: '',
    },
    multiple: {
      type: Boolean,
      default: false,
    },
    maxFileSize: {
      type: Number,
      default: 10 * 1024 * 1024, // 10MB default
    },
    disable: {
      type: Boolean,
      default: false,
    },
    size: {
      type: String,
      default: 'md',
      validator: (value: string) => ['sm', 'md', 'lg'].includes(value),
    },
    icon: {
      type: String,
      default: 'cloud_upload',
    },
    actionText: {
      type: String,
      default: 'Click to upload',
    },
    dragText: {
      type: String,
      default: 'or drag and drop',
    },
    hint: {
      type: String,
      default: '',
    },
  },
  emits: ['update:modelValue', 'error'],
  setup(props, { emit }) {
    const fileInput = ref<HTMLInputElement | null>(null);
    const isDragging = ref(false);

    const sizeClass = computed(() => `f-file--${props.size}`);

    const hasFile = computed(() => props.modelValue !== null);

    const fileName = computed(() => {
      if (props.modelValue instanceof File) {
        return props.modelValue.name;
      }
      return '';
    });

    const fileSize = computed(() => {
      if (props.modelValue instanceof File) {
        return props.modelValue.size;
      }
      return 0;
    });

    const formattedFileSize = computed(() => {
      const size = fileSize.value;
      if (size < 1024) return `${size} B`;
      if (size < 1024 * 1024) return `${(size / 1024).toFixed(1)} KB`;
      return `${(size / (1024 * 1024)).toFixed(1)} MB`;
    });

    const iconSize = computed(() => {
      switch (props.size) {
        case 'sm':
          return '20px';
        case 'lg':
          return '32px';
        default:
          return '24px';
      }
    });

    const openFilePicker = () => {
      if (props.disable) return;
      fileInput.value?.click();
    };

    const validateFile = (file: File): boolean => {
      if (file.size > props.maxFileSize) {
        emit('error', {
          type: 'size',
          message: `File size exceeds maximum allowed size of ${(props.maxFileSize / (1024 * 1024)).toFixed(0)}MB`,
        });
        return false;
      }

      if (props.accept) {
        const acceptedTypes = props.accept.split(',').map((t) => t.trim());
        const fileType = file.type;
        const fileExtension = '.' + file.name.split('.').pop()?.toLowerCase();

        const isAccepted = acceptedTypes.some((type) => {
          if (type.startsWith('.')) {
            return fileExtension === type.toLowerCase();
          }
          if (type.endsWith('/*')) {
            return fileType.startsWith(type.replace('/*', '/'));
          }
          return fileType === type;
        });

        if (!isAccepted) {
          emit('error', {
            type: 'type',
            message: `File type not accepted. Accepted types: ${props.accept}`,
          });
          return false;
        }
      }

      return true;
    };

    const handleFile = (file: File) => {
      if (validateFile(file)) {
        emit('update:modelValue', file);
      }
    };

    const onFileChange = (event: Event) => {
      const target = event.target as HTMLInputElement;
      const files = target.files;
      if (files && files.length > 0) {
        handleFile(files[0]);
      }
      // Reset input so same file can be selected again
      target.value = '';
    };

    const onDragOver = () => {
      if (props.disable) return;
      isDragging.value = true;
    };

    const onDragLeave = () => {
      isDragging.value = false;
    };

    const onDrop = (event: DragEvent) => {
      isDragging.value = false;
      if (props.disable) return;

      const files = event.dataTransfer?.files;
      if (files && files.length > 0) {
        handleFile(files[0]);
      }
    };

    const clearFile = () => {
      emit('update:modelValue', null);
    };

    return {
      fileInput,
      isDragging,
      sizeClass,
      hasFile,
      fileName,
      fileSize,
      formattedFileSize,
      iconSize,
      openFilePicker,
      onFileChange,
      onDragOver,
      onDragLeave,
      onDrop,
      clearFile,
    };
  },
});
</script>

