<template>
  <a
    :href="resolvedUrl"
    target="_blank"
    rel="noopener noreferrer"
    :aria-label="resolvedTooltip"
    :data-test="dataTest"
    class="help-link"
  >
    <Icon :icon="iconName" class="size-4 text-muted-foreground hover:text-foreground transition-colors" />
    <q-tooltip>{{ resolvedTooltip }}</q-tooltip>
  </a>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { Icon } from '@iconify/vue';
import { getLink } from 'src/utils/helpLinks';

export default defineComponent({
  name: 'HelpLink',

  components: { Icon },

  props: {
    name: {
      type: String,
      required: true,
    },
    tooltip: {
      type: String,
      default: '',
    },
    iconName: {
      type: String,
      default: 'mdi:help-circle-outline',
    },
    dataTest: {
      type: String,
      default: 'help-link',
    },
  },

  computed: {
    resolvedUrl(): string {
      return getLink(this.name);
    },
    resolvedTooltip(): string {
      return this.tooltip || this.$t('learn_more');
    },
  },
});
</script>

