/**
 * API SDK Service - Configure generated API SDK with authentication
 *
 * This service configures the generated-api-sdk (from openapi-typescript-codegen)
 * with proper authentication tokens, similar to how authSdkService.ts configures
 * the generated-auth-sdk.
 *
 * The generated-api-sdk is used by components like WatchdogLogsCard.vue
 * via OrganizationLogsService to fetch data from the API.
 *
 * Without this configuration, API calls return 401 Unauthorized because
 * the SDK's OpenAPI.TOKEN is undefined by default.
 *
 * @see /src/generated-api-sdk - Generated from doc2-api OpenAPI spec
 * @see /src/services/user/authSdkService.ts - Similar pattern for auth SDK
 */

import { OpenAPI } from 'src/generated-api-sdk';
// Direct imports avoid barrel re-exports that pull all stores into the main chunk
import { useAuthTokenStore } from 'src/store/User/auth_token.store';
import { onApiBaseUrlChange } from 'src/pages/api-base-url';

const initializeApiSdk = () => {
  onApiBaseUrlChange((url) => {
    OpenAPI.BASE = url;
  });

  // Dynamic headers resolver - adds Bearer token to Authorization header
  // Note: We use HEADERS instead of TOKEN because the SDK's TOKEN creates
  // a "Basic" auth header, but the API expects "Bearer" tokens
  OpenAPI.HEADERS = async () => {
    const authStore = useAuthTokenStore();
    const token = authStore.token;
    if (token) {
      return {
        Authorization: `Bearer ${token}`,
      };
    }
    return {};
  };

  // Enable credentials for cross-origin requests
  OpenAPI.WITH_CREDENTIALS = true;
  OpenAPI.CREDENTIALS = 'include';
};

// Initialize on module load
initializeApiSdk();

export { OpenAPI };
