// Cross-tab logout: `token_details` being REMOVED is the signal. Every path
// that ends a session removes that key, and a localStorage removal fires a
// native 'storage' event in every other tab — including tabs Chrome froze,
// whose queued events run on resume. Nothing needs to re-check later.
//
// A silent token refresh REWRITES the key, so `newValue` distinguishes the two;
// the org-switch listener in src/boot/main.js owns the write case.
//
// Lives outside the boot file so it stays importable on its own — the boot file
// pulls in the whole component graph, which a unit test cannot load.
export function handleSessionClearedFromOtherTab(
  event?: Partial<StorageEvent> | null,
): void {
  const wholesaleClear = event?.key === null; // localStorage.clear() elsewhere
  if (!wholesaleClear && event?.key !== 'token_details') return;
  if (event?.newValue) return; // written, not removed
  if (wholesaleClear && window.localStorage.getItem('token_details')) return;
  console.warn('[Boot] Session cleared by another tab — hard-reloading to /');
  window.location.href = '/';
}
