import { registerComponents } from 'src/components/register';
import NewTabDirective from 'src/directives/new-tab.js';
import FellowToggle from 'src/single-component/FellowToggle.vue';
import FellowButton from 'src/single-component/FellowButton.vue';
import FellowFile from 'src/single-component/FellowFile.vue';
import FellowInput from 'src/single-component/FellowInput.vue';
import DocbitsAccordionPanel from 'src/single-component/DocbitsAccordionPanel.vue';
import Vue3DraggableResizable from 'vue3-draggable-resizable';
import { safeBoot } from 'src/utils/bootSafety';
import { tabChannel } from 'src/utils/LogoutUtil';
import { handleTokenDetailsStorageEvent } from 'src/utils/crossTabSessionSync';
import { handleSessionClearedFromOtherTab } from 'src/utils/crossTabLogout';

// Configure generated API SDK with authentication (fixes 401 errors for SDK-based API calls)
import 'src/services/apiSdkService';

/**
 * PERFORMANCE OPTIMIZATION (Issue #13858)
 *
 * Boot file optimized for faster FCP/LCP:
 * - CRITICAL operations run synchronously (directives, components, error handlers)
 * - NON-CRITICAL operations deferred using requestIdleCallback/setTimeout
 *
 * Deferred operations:
 * - PWA cache recovery (already async)
 * - Auth environment validator
 * - Online/offline listeners
 */

// Helper: Schedule non-critical work after first paint
const deferNonCritical = (callback, timeout = 2000) => {
  if (typeof requestIdleCallback !== 'undefined') {
    requestIdleCallback(callback, { timeout });
  } else {
    // Fallback for Safari and older browsers
    setTimeout(callback, 50);
  }
};

// LOGOUT from another tab → hard-reload to /. The reload itself is the
// cleanup (wipes Pinia, axios, vue-sonner). Skip if this tab initiated:
// a same-tab duplicate channel would otherwise stack an extra reload.
export function handleCrossTabMessage(event) {
  if (event?.data?.type !== 'LOGOUT') return;
  if (window.__docbits_logging_out) return;
  console.warn('[Boot] LOGOUT received from another tab — hard-reloading to /');
  window.location.href = '/';
}


// PWA cache recovery - extracted for deferred execution
const performPWACacheRecovery = async () => {
  try {
    const { pwaCacheManager } = await import('src/utils/pwaCache');
    const logger = (await import('src/utils/logger')).default;

    const recovered = await pwaCacheManager.autoRecoverIfNeeded();
    if (recovered) {
      logger.info('[Boot] PWA cache version updated. Fresh content will load on next navigation.');
    }
  } catch (error) {
    // Continue with app startup even if cache recovery fails
  }
};

// Auth and network listeners - extracted for deferred execution
const setupAuthAndNetworkListeners = () => {
  if (typeof window === 'undefined') return;

  // Online/offline event listeners for automatic token refresh
  window.addEventListener('online', async () => {
    try {
      const { useAuthTokenStore } = await import('src/store/main');
      const auth_token_store = useAuthTokenStore();
      const tokenExpired = auth_token_store.isTokenExpired();

      if (tokenExpired) {
        await auth_token_store.refreshToken();
      }
    } catch (error) {
      // Silently handle - not critical for app startup
    }
  });

  // Initialize auth environment validator
  import('src/utils/auth-environment-validator')
    .then(({ initializeAuthEnvironmentValidator }) => {
      initializeAuthEnvironmentValidator();
    })
    .catch(() => {
      // Non-critical - continue without validator
    });
};

export default safeBoot('main', ({ app }) => {
  // ═══════════════════════════════════════════════════════════════════════════
  // CRITICAL PATH - Run synchronously (required for first render)
  // ═══════════════════════════════════════════════════════════════════════════

  // Register directives and components immediately
  app.directive('new-tab', NewTabDirective);
  app.component('f-toggle', FellowToggle);
  app.component('f-btn', FellowButton);
  app.component('f-file', FellowFile);
  app.component('f-input', FellowInput);
  app.component('docbits-accordion-panel', DocbitsAccordionPanel);
  app.use(Vue3DraggableResizable);

  // Register all global components
  registerComponents(app);

  // Swallow single chunk-load errors — they're usually transient (SW handover,
  // brief network blip) and Vue retries the import on the user's next click.
  // Reload only when 2 errors hit within 30s (real deployment with missing chunks).
  let chunkErrors = 0;
  let chunkErrorResetTimer = null;

  window.addEventListener('unhandledrejection', (event) => {
    const msg = event.reason?.message || '';
    const isChunkError =
      event.reason?.name === 'ChunkLoadError' ||
      msg.includes('Failed to fetch dynamically imported module') ||
      msg.includes('error loading dynamically imported module') ||
      msg.includes('Loading chunk') ||
      msg.includes('Importing a module script failed') ||
      msg.includes('Couldn\'t resolve component "default"');

    if (!isChunkError) return;

    event.preventDefault(); // don't bubble to global error handler
    chunkErrors++;

    clearTimeout(chunkErrorResetTimer);
    chunkErrorResetTimer = setTimeout(() => { chunkErrors = 0; }, 30000);

    console.warn(`[Boot] Chunk load error (${chunkErrors}/2):`, msg || event.reason);

    if (chunkErrors >= 2 && !sessionStorage.getItem('lastChunkReload')) {
      sessionStorage.setItem('lastChunkReload', String(Date.now()));
      window.location.reload();
    }
  });

  // Set up global error handler (must be sync for immediate error catching).
  // Chunk-error handling lives in the unhandledrejection listener above — do
  // NOT duplicate it here (the same error would fire both paths and race).
  app.config.errorHandler = (err, vm, info) => {
    // Skip error handling if suppressed by AccessAudit component
    if (window.__suppressAuditErrorHandler) {
      console.log('Error handler suppressed for AccessAudit:', err);
      return;
    }

    // Also skip if the error is coming from AccessAudit component
    if (vm?.$options?.name === 'AccessAudit' ||
        vm?.$parent?.$options?.name === 'AccessAudit' ||
        err.message?.includes('audit') ||
        err.message?.includes('AuditTrail') ||
        info?.includes('AccessAudit')) {
      console.log('Error suppressed for AccessAudit component:', err);
      return;
    }

    // Skip network/API errors (these should not trigger page reloads)
    if (
      err.message &&
      (err.message.includes('Network Error') ||
        err.message.includes('fetch') ||
        err.message.includes('axios') ||
        err.message.includes('Request failed') ||
        err.message.includes('status code') ||
        err.message.includes('timeout') ||
        err.code === 'NETWORK_ERROR' ||
        err.code === 'ECONNREFUSED' ||
        err.code === 'ETIMEDOUT')
    ) {
      console.log('Network/API error - not triggering page reload:', err);
      return;
    }

    // Only handle actual storage quota errors — free up space using the same
    // keep-list logic as logout so user preferences survive the cleanup.
    if (
      err.message &&
      (err.message.includes('QuotaExceededError') ||
        err.message.includes('quota exceeded') ||
        err.name === 'QuotaExceededError')
    ) {
      import('src/utils/LogoutUtil')
        .then(({ clearStorageForLogout }) => {
          clearStorageForLogout();
        })
        .catch(() => {
          // Ignore
        });
    }
  };

  // Cross-tab logout (see src/utils/crossTabLogout.ts). Its own listener
  // rather than folded into the org-switch handler below: that one only cares
  // about token_details being WRITTEN, this one about it being REMOVED.
  window.addEventListener('storage', handleSessionClearedFromOtherTab);

  // Cross-tab session sync on token_details: org switch (DOCB-13399), user
  // switch and session removal (DOCB-13889). Handler + rationale live in
  // src/utils/crossTabSessionSync.js so specs can exercise it in isolation.
  window.addEventListener('storage', handleTokenDetailsStorageEvent);

  // ═══════════════════════════════════════════════════════════════════════════
  // NON-CRITICAL PATH - Defer to after first paint for better FCP/LCP
  // ═══════════════════════════════════════════════════════════════════════════

  // Defer PWA cache recovery - not blocking for login page
  deferNonCritical(() => {
    performPWACacheRecovery();
  }, 1500);

  // Defer auth listeners - only needed after user interaction
  deferNonCritical(() => {
    setupAuthAndNetworkListeners();
  }, 2000);
});
