<template>
  <div
    class="f-input"
    :class="rootClasses"
  >
    <!-- Before: outside left -->
    <div v-if="hasBefore" class="f-input__before">
      <slot name="before">
        <q-icon v-if="prependIcon" :name="prependIcon" :size="computedIconSize" />
      </slot>
    </div>

    <!-- Main field wrapper -->
    <div class="f-input__field-wrapper">
      <!-- Field control (bordered area) — label lives INSIDE here -->
      <div
        class="f-input__control"
        :class="{
          'f-input__control--focused': isFocused,
          'f-input__control--error': hasError,
          'f-input__control--disabled': disabled,
          'f-input__control--readonly': readonly,
          'f-input__control--labeled': hasLabel && !stackLabel,
        }"
        @click="focusInput"
      >
        <!-- Prefix -->
        <span v-if="prefix" class="f-input__prefix">{{ prefix }}</span>

        <!-- Prepend inner -->
        <div v-if="hasPrepend" class="f-input__prepend">
          <slot name="prepend">
            <q-icon v-if="prependInnerIcon" :name="prependInnerIcon" :size="computedIconSize" />
          </slot>
        </div>

        <!-- Input area with floating label -->
        <div class="f-input__input-wrap">
          <!-- Floating label — inside the control, overlays the input -->
          <label
            v-if="hasLabel && !stackLabel"
            class="f-input__label"
            :class="{
              'f-input__label--float': labelFloated,
              'f-input__label--focused': isFocused,
              'f-input__label--error': hasError,
            }"
          >
            <slot name="label">{{ label }}</slot>
          </label>

          <!-- Native input -->
          <textarea
            v-if="textarea"
            ref="inputRef"
            class="f-input__native f-input__native--textarea"
            :class="[inputClass, { 'f-input__native--label-floated': hasLabel && !stackLabel && labelFloated }]"
            :style="inputStyle"
            :value="displayValue"
            :placeholder="effectivePlaceholder"
            :disabled="disabled"
            :readonly="readonly"
            :name="name || undefined"
            :autocomplete="autocomplete"
            :maxlength="maxlength || undefined"
            :rows="rows"
            @input="onInput"
            @focus="onFocus"
            @blur="onBlur"
            @keyup="$emit('keyup', $event)"
            @keydown="$emit('keydown', $event)"
            @change="$emit('change', $event)"
          />
          <input
            v-else
            ref="inputRef"
            class="f-input__native"
            :class="[inputClass, { 'f-input__native--label-floated': hasLabel && !stackLabel && labelFloated }]"
            :style="inputStyle"
            :type="type"
            :value="displayValue"
            :placeholder="effectivePlaceholder"
            :disabled="disabled"
            :readonly="readonly"
            :name="name || undefined"
            :autocomplete="autocomplete"
            :maxlength="maxlength || undefined"
            @input="onInput"
            @focus="onFocus"
            @blur="onBlur"
            @keyup="$emit('keyup', $event)"
            @keydown="$emit('keydown', $event)"
            @change="$emit('change', $event)"
          />
        </div>

        <!-- Suffix -->
        <span v-if="suffix" class="f-input__suffix">{{ suffix }}</span>

        <!-- Append inner -->
        <div v-if="hasAppend" class="f-input__append">
          <slot name="append">
            <q-icon v-if="appendInnerIcon" :name="appendInnerIcon" :size="computedIconSize" />
          </slot>
        </div>

        <!-- Clear button -->
        <button
          v-if="showClear"
          class="f-input__clear"
          type="button"
          tabindex="-1"
          @click.stop="onClear"
        >
          <q-icon name="cancel" :size="computedIconSize" />
        </button>

        <!-- Loading spinner -->
        <div v-if="loading" class="f-input__loading">
          <slot name="loading">
            <q-spinner :size="computedIconSize" color="primary" />
          </slot>
        </div>
      </div>

      <!-- Stacked label — above the control (outside) -->
      <label
        v-if="hasLabel && stackLabel"
        class="f-input__stack-label"
        :class="{
          'f-input__stack-label--focused': isFocused,
          'f-input__stack-label--error': hasError,
        }"
        @click="focusInput"
      >
        <slot name="label">{{ label }}</slot>
      </label>

      <!-- Bottom row: ALWAYS reserves space to prevent shifting -->
      <div class="f-input__bottom" :class="{ 'f-input__bottom--hidden': !showBottom }">
        <div class="f-input__message" :class="{ 'f-input__message--error': hasError }">
          <template v-if="hasError">
            <slot name="error">{{ validationMessage || errorMessage }}</slot>
          </template>
          <template v-else>
            <slot name="hint">{{ hint }}</slot>
          </template>
        </div>
        <div v-if="counter && maxlength" class="f-input__counter">
          <slot name="counter">{{ charCount }}/{{ maxlength }}</slot>
        </div>
      </div>
    </div>

    <!-- After: outside right -->
    <div v-if="hasAfter" class="f-input__after">
      <slot name="after">
        <q-icon v-if="appendIcon" :name="appendIcon" :size="computedIconSize" />
      </slot>
    </div>
  </div>
</template>

<script>
import { defineComponent } from 'vue';

// Mask helper: applies a pattern like '####-##-##' to raw input
function applyMask(raw, mask, fillChar) {
  if (!mask) return raw;
  const digits = raw.replace(/[^a-zA-Z0-9]/g, '');
  let result = '';
  let dIdx = 0;
  for (let i = 0; i < mask.length && dIdx < digits.length; i++) {
    if (mask[i] === '#') {
      result += digits[dIdx++];
    } else {
      result += mask[i];
    }
  }
  // Fill remaining mask positions if fillMask is set
  if (fillChar && result.length < mask.length) {
    for (let i = result.length; i < mask.length; i++) {
      if (mask[i] === '#') {
        result += typeof fillChar === 'string' ? fillChar : '_';
      } else {
        result += mask[i];
      }
    }
  }
  return result;
}

export default defineComponent({
  name: 'FellowInput',

  props: {
    modelValue: {
      type: [String, Number],
      default: '',
    },
    type: {
      type: String,
      default: 'text',
    },
    textarea: {
      type: Boolean,
      default: false,
    },
    autogrow: {
      type: Boolean,
      default: false,
    },
    rows: {
      type: Number,
      default: 3,
    },
    size: {
      type: String,
      default: 'md',
      validator: (v) => ['xs', 'sm', 'md', 'lg'].includes(v),
    },
    label: {
      type: String,
      default: '',
    },
    stackLabel: {
      type: Boolean,
      default: false,
    },
    placeholder: {
      type: String,
      default: '',
    },
    hint: {
      type: String,
      default: '',
    },
    disabled: {
      type: Boolean,
      default: false,
    },
    readonly: {
      type: Boolean,
      default: false,
    },
    clearable: {
      type: Boolean,
      default: false,
    },
    error: {
      type: Boolean,
      default: false,
    },
    errorMessage: {
      type: String,
      default: '',
    },
    rules: {
      type: Array,
      default: () => [],
    },
    lazyRules: {
      type: [Boolean, String],
      default: false,
    },
    mask: {
      type: String,
      default: '',
    },
    fillMask: {
      type: [Boolean, String],
      default: false,
    },
    prefix: {
      type: String,
      default: '',
    },
    suffix: {
      type: String,
      default: '',
    },
    debounce: {
      type: Number,
      default: 0,
    },
    maxlength: {
      type: Number,
      default: undefined,
    },
    counter: {
      type: Boolean,
      default: false,
    },
    loading: {
      type: Boolean,
      default: false,
    },
    hideBottomSpace: {
      type: Boolean,
      default: false,
    },
    dense: {
      type: Boolean,
      default: undefined,
    },
    prependIcon: {
      type: String,
      default: '',
    },
    appendIcon: {
      type: String,
      default: '',
    },
    prependInnerIcon: {
      type: String,
      default: '',
    },
    appendInnerIcon: {
      type: String,
      default: '',
    },
    iconSize: {
      type: String,
      default: '',
    },
    name: {
      type: String,
      default: '',
    },
    autocomplete: {
      type: String,
      default: 'off',
    },
    autofocus: {
      type: Boolean,
      default: false,
    },
    inputClass: {
      type: String,
      default: '',
    },
    inputStyle: {
      type: [String, Object],
      default: '',
    },
  },

  emits: ['update:modelValue', 'focus', 'blur', 'clear', 'keyup', 'keydown', 'change'],

  data() {
    return {
      isFocused: false,
      internalError: false,
      internalErrorMessage: '',
      hasBlurred: false,
      debounceTimer: null,
    };
  },

  computed: {
    isDense() {
      if (this.dense !== undefined) return this.dense;
      return this.size !== 'lg';
    },

    hasValue() {
      return this.modelValue !== '' && this.modelValue !== null && this.modelValue !== undefined;
    },

    hasError() {
      return this.error || this.internalError;
    },

    validationMessage() {
      return this.internalErrorMessage;
    },

    displayValue() {
      const val = this.modelValue == null ? '' : String(this.modelValue);
      if (this.mask) {
        return applyMask(val, this.mask, this.fillMask);
      }
      return val;
    },

    // Label floats up when focused or has a value
    labelFloated() {
      return this.isFocused || this.hasValue;
    },

    effectivePlaceholder() {
      // Hide placeholder when floating label is in resting (center) position
      if (this.hasLabel && !this.stackLabel && !this.labelFloated) {
        return '';
      }
      return this.placeholder;
    },

    showClear() {
      return this.clearable && this.hasValue && !this.disabled && !this.readonly;
    },

    showBottom() {
      if (this.hideBottomSpace) {
        return this.hasError || (this.counter && this.maxlength);
      }
      return !!(this.hint || this.errorMessage || this.hasError || (this.counter && this.maxlength));
    },

    charCount() {
      return this.modelValue == null ? 0 : String(this.modelValue).length;
    },

    hasLabel() {
      return !!(this.label || this.$slots.label);
    },

    hasPrepend() {
      return !!(this.prependInnerIcon || this.$slots.prepend);
    },

    hasAppend() {
      return !!(this.appendInnerIcon || this.$slots.append);
    },

    hasBefore() {
      return !!(this.prependIcon || this.$slots.before);
    },

    hasAfter() {
      return !!(this.appendIcon || this.$slots.after);
    },

    computedIconSize() {
      if (this.iconSize) return this.iconSize;
      const sizes = { xs: '14px', sm: '16px', md: '18px', lg: '22px' };
      return sizes[this.size] || '18px';
    },

    rootClasses() {
      const classes = [
        `f-input--size-${this.size}`,
      ];
      if (this.isDense) classes.push('f-input--dense');
      if (this.disabled) classes.push('f-input--disabled');
      if (this.readonly) classes.push('f-input--readonly');
      if (this.hasError) classes.push('f-input--error');
      if (this.isFocused) classes.push('f-input--focused');
      if (this.hasLabel && !this.stackLabel) classes.push('f-input--has-floating-label');
      return classes;
    },
  },

  mounted() {
    if (this.autofocus) {
      this.$nextTick(() => this.focus());
    }
    if (this.textarea && this.autogrow) {
      this.$nextTick(() => this.adjustTextareaHeight());
    }
  },

  beforeUnmount() {
    if (this.debounceTimer) {
      clearTimeout(this.debounceTimer);
    }
  },

  methods: {
    focus() {
      this.$refs.inputRef?.focus();
    },

    blur() {
      this.$refs.inputRef?.blur();
    },

    validate() {
      if (!this.rules || this.rules.length === 0) {
        this.internalError = false;
        this.internalErrorMessage = '';
        return true;
      }
      const val = this.modelValue;
      for (const rule of this.rules) {
        const result = rule(val);
        if (result !== true && result !== undefined && result !== null) {
          this.internalError = true;
          this.internalErrorMessage = typeof result === 'string' ? result : 'Validation failed';
          return false;
        }
      }
      this.internalError = false;
      this.internalErrorMessage = '';
      return true;
    },

    resetValidation() {
      this.internalError = false;
      this.internalErrorMessage = '';
      this.hasBlurred = false;
    },

    focusInput() {
      if (!this.disabled && !this.readonly) {
        this.focus();
      }
    },

    onInput(event) {
      let val = event.target.value;

      // Apply mask: strip non-alphanumeric, then store raw
      if (this.mask) {
        val = val.replace(/[^a-zA-Z0-9]/g, '');
        // Re-render masked display
        event.target.value = applyMask(val, this.mask, this.fillMask);
      }

      const emitValue = this.type === 'number' && val !== '' ? Number(val) : val;

      if (this.debounce > 0) {
        if (this.debounceTimer) clearTimeout(this.debounceTimer);
        this.debounceTimer = setTimeout(() => {
          this.$emit('update:modelValue', emitValue);
        }, this.debounce);
      } else {
        this.$emit('update:modelValue', emitValue);
      }

      // Run validation if not lazy
      if (this.rules.length > 0 && !this.lazyRules) {
        this.$nextTick(() => this.validate());
      }

      // Autogrow
      if (this.textarea && this.autogrow) {
        this.$nextTick(() => this.adjustTextareaHeight());
      }
    },

    onFocus(event) {
      this.isFocused = true;
      this.$emit('focus', event);
    },

    onBlur(event) {
      this.isFocused = false;
      this.hasBlurred = true;
      this.$emit('blur', event);

      // Lazy validation: run on first blur
      if (this.rules.length > 0 && this.lazyRules && this.lazyRules !== 'ondemand') {
        this.validate();
      }
    },

    onClear() {
      this.$emit('update:modelValue', '');
      this.$emit('clear');
      this.$nextTick(() => this.focus());

      if (this.rules.length > 0 && !this.lazyRules) {
        this.$nextTick(() => this.validate());
      }
    },

    adjustTextareaHeight() {
      const el = this.$refs.inputRef;
      if (!el) return;
      el.style.height = 'auto';
      el.style.height = el.scrollHeight + 'px';
    },
  },
});
</script>

