// Cross-tab session sync on the `token_details` LocalStorage entry.
// Registered on window's 'storage' event by src/boot/main.js — the native
// event fires in every OTHER tab, never the writer, so no self-send guard is
// needed for writes. Leaf module (no store/service imports) so boot files can
// import it directly and specs can exercise it in isolation.
//
// Quasar's Storage plugin doesn't store plain values — see encode()/decode()
// in node_modules/quasar/src/plugins/storage/engine/web-storage.js. We read
// the RAW native Storage API here (StorageEvent values, sessionStorage
// directly) rather than the Quasar wrapper — deliberately synchronous, no
// dynamic import, no microtask gap between detecting an org switch and
// seeding active_org_id (a Codex review of DOCB-13399 flagged an earlier
// async-import version for exactly that gap: a request firing between the
// storage event and an async getOrgId() could send the NEW token with the
// OLD X-ORG-ID header, tripping flask_auth.py's fail-closed org guard).

const QUASAR_OBJECT_PREFIX = '__q_objt|';
const QUASAR_STRING_PREFIX = '__q_strn|';

function decodeQuasarStorageValue(raw, prefix) {
  return raw && raw.startsWith(prefix) ? raw.slice(prefix.length) : raw;
}

// Handles three distinct situations:
//   1. Removal (DOCB-13889): another tab wiped the session (logout) and this
//      tab missed the LOGOUT broadcast (frozen/suspended tab) — hard-reload
//      to '/', same semantics as boot/main.js handleCrossTabMessage.
//   2. user_id change (DOCB-13889): another tab logged in as a DIFFERENT
//      user. With the same org the org_id compare below never fires, leaving
//      this tab's whole in-memory session (Pinia, user_details caches) stale
//      over the new user's tokens → auth errors on the next interaction.
//      Reload into the new session.
//   3. org_id change (DOCB-13399, Multi-Org Login SD 2860679170 §4.2, T2.8):
//      org switch from another tab — seed active_org_id and reload so the
//      first post-reload request already sends the matching X-ORG-ID
//      (flask_auth.py is fail-closed on a header/token org mismatch).
// A plain silent token refresh also rewrites token_details, but user_id and
// org_id are unchanged/absent (OAuth2TokenResponse) — naturally ignored.
export function handleTokenDetailsStorageEvent(event) {
  if (event.key !== 'token_details') return;
  if (window.__docbits_logging_out) return;

  if (!event.newValue) {
    if (event.oldValue) {
      console.warn(
        '[Boot] token_details removed by another tab — hard-reloading to /',
      );
      window.location.href = '/';
    }
    return;
  }

  let newOrgId;
  let newUserId;
  try {
    const parsed = JSON.parse(
      decodeQuasarStorageValue(event.newValue, QUASAR_OBJECT_PREFIX),
    );
    newOrgId = parsed?.org_id;
    newUserId = parsed?.user_id;
  } catch {
    return; // Malformed payload — ignore, not our concern here.
  }

  if (newUserId && event.oldValue) {
    try {
      const oldUserId = JSON.parse(
        decodeQuasarStorageValue(event.oldValue, QUASAR_OBJECT_PREFIX),
      )?.user_id;
      if (oldUserId && String(oldUserId) !== String(newUserId)) {
        console.warn(
          '[Boot] User switch detected from another tab — reloading',
        );
        window.location.reload();
        return;
      }
    } catch {
      // Unparseable old value — fall through to the org check.
    }
  }

  if (!newOrgId) return;

  // Synchronous, native read — no getOrgId()/Pinia import in the hot path.
  const currentOrgIdRaw = window.sessionStorage.getItem('active_org_id');
  const currentOrgId = currentOrgIdRaw
    ? decodeQuasarStorageValue(currentOrgIdRaw, QUASAR_STRING_PREFIX)
    : null;
  if (newOrgId === currentOrgId) return; // Already this org — nothing to do.

  console.warn(
    '[Boot] Organisation switch detected from another tab — reloading into',
    newOrgId,
  );
  // Seed active_org_id BEFORE the reload so the very first post-reload
  // request already sends the matching X-ORG-ID for the new token. Written
  // via the native API with the same encoding Quasar's SessionStorage.set()
  // uses, so org_id_helper.ts's SessionStorage.getItem() decodes it normally.
  window.sessionStorage.setItem(
    'active_org_id',
    QUASAR_STRING_PREFIX + String(newOrgId),
  );
  window.location.reload();
}
